import java.util.*;

class Solution {
  public int treeDiameter(int[][] edges) {
    int n = edges.length + 1;
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
    for (int[] e : edges) {
      adj.get(e[0]).add(e[1]);
      adj.get(e[1]).add(e[0]);
    }
    // the farthest node from anywhere is one end of a diameter
    int[] first = farthest(adj, 0);
    return farthest(adj, first[0])[1];
  }

  // {farthest node, its distance}
  private int[] farthest(List<List<Integer>> adj, int start) {
    int[] dist = new int[adj.size()];
    Arrays.fill(dist, -1);
    dist[start] = 0;
    Deque<Integer> q = new ArrayDeque<>();
    q.add(start);
    int last = start;
    while (!q.isEmpty()) {
      last = q.poll();
      for (int nb : adj.get(last))
        if (dist[nb] < 0) {
          dist[nb] = dist[last] + 1;
          q.add(nb);
        }
    }
    return new int[] {last, dist[last]};
  }
}
